    any_int(3, -2, 1) ➞ True

    any_int(3.6, -2.2, 2) ➞ False
    '''
    def is_integer(n):
        if isinstance(n, bool):
            return False
        if isinstance(n, int):
            return True
        if isinstance(n, float):
            return n.is_integer()
        return False

    if not (is_integer(x) and is_integer(y) and is_integer(z)):
        return False

    return (x + y == z) or (x + z == y) or (y + z == x)

def is_nested(string):
    opens = [i for i, c in enumerate(string) if c == '[']
    if len(opens) < 2:
        return False
    second_open = opens[1]
    return string[second_open + 1:].count(']') >= 2
